def roman_to_int(s):
    if not isinstance(s, str):
        raise TypeError("Input must be a string")
    if s == "":
        raise ValueError("Input string is empty")

    # Valid characters and their values
    values = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}

    # Check for invalid characters
    for ch in s:
        if ch not in values:
            raise ValueError(f"Invalid character '{ch}'")

    # Check for non-canonical forms (more than 3 repeats of I, X, C, M)
    # We can do this by checking the counts of consecutive identical characters
    i = 0
    while i < len(s):
        j = i
        while j < len(s) and s[j] == s[i]:
            j += 1
        count = j - i
        if count > 3 and s[i] in ('I', 'X', 'C', 'M'):
            raise ValueError(f"Non-canonical numeral: more than 3 repeats of '{s[i]}'")
        i = j

    # Convert to integer
    total = 0
    prev_value = 0
    for ch in s:
        current_value = values[ch]
        if current_value < prev_value:
            total -= current_value
        else:
            total += current_value
        prev_value = current_value

    return total
