    if not hour_str or not minute_str:
        raise ValueError("Empty hour or minute")

    if len(hour_str) < 1 or len(hour_str) > 2:
        raise ValueError("Invalid hour length")

    if len(minute_str) != 2:
        raise ValueError("Minutes must be exactly two digits")

    # Validate hour value
    try:
        hour = int(hour_str)
    except ValueError:
        raise ValueError("Hour must be numeric")

    if hour < 1 or hour > 12:
        raise ValueError("Hour must be between 1 and 12")

    # Validate minute value
    try:
        minute = int(minute_str)
    except ValueError:
        raise ValueError("Minutes must be numeric")

    if minute < 0 or minute > 59:
