    if suffix not in ("AM", "PM", "am", "pm", "A.M.", "P.M.", "a.m.", "p.m."):
        raise ValueError("Unknown suffix")

    # Convert to 24-hour format
    suffix_upper = suffix.upper()
    if suffix_upper == "AM":
        if hour == 12:
            hour = 0
    elif suffix_upper == "PM":
        if hour != 12:
            hour += 12

